def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    x = clip(rng.uniform(lb, ub, size=dim), lb, ub)
    best_x = x.copy()
    best_f = func(x)
    hill_valley_region = np.inf

    for _ in range(budget - 1):
        noise = rng.uniform(-0.5, 0.5, size=dim)
        x_noisy = clip(x + noise, lb, ub)

        f_noisy = func(x_noisy)
        hill_valley_region_new = np.abs(best_f - f_noisy) / (1 + np.sum(np.abs(x_noisy - best_x)))

        if hill_valley_region_new > hill_valley_region:
            x = x_noisy
            hill_valley_region = hill_valley_region_new

        if f_noisy < best_f:
            best_f = f_noisy
            best_x = x_noisy

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def evaluate(x):
        x = clip(x)
        return func(x)

    def cma_es(dim, lb, ub, budget, num_restarts=10, tol=1e-6, sigma_init=0.5, step_size=0.5):
        for _ in range(num_restarts):
            w = np.random.randn(dim) * 0.01
            cov = np.eye(dim)
            mu = np.zeros(dim)

            for i in range(budget // num_restarts):
                d = np.random.multivariate_normal(mu, cov) * sigma_init
                x = clip(mu + d)

                fx = evaluate(x)
                fmu = evaluate(mu)

                if fx < fmu:
                    mu = x
                    cov *= 1.0 + step_size

            if i % 100 == 0 and i != 0:
                print(f'Iteration {i}, Best fitness: {evaluate(mu)}')

        return mu, evaluate(mu)

    best_solution, best_fitness = cma_es(dim, lb, ub, budget)
    return best_solution
